import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"UPnPumpkin plugin API","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/apis/upnpumpkin-api/docs/index.md"},"headers":[],"relativePath":"tools/apis/upnpumpkin-api/docs/index.md","filePath":"tools/apis/upnpumpkin-api/docs/index.md","lastUpdated":1792508847000}`),a={name:`tools/apis/upnpumpkin-api/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="upnpumpkin-plugin-api" tabindex="-1">UPnPumpkin plugin API <a class="header-anchor" href="#upnpumpkin-plugin-api" aria-label="Permalink to “UPnPumpkin plugin API”">​</a></h1><p><code>@pumpkin-plugins/upnpumpkin-api</code> lets your plugin ask UPnPumpkin to make a local port reachable from the internet. It sends requests through Pumpkin plugin messages; UPnPumpkin handles router discovery and port mapping. The package provides the message protocol, a client, a watcher that keeps a request alive, and a helper for building a public URL when the port is open.</p><h2 id="watch-a-mapping" tabindex="-1">Watch a mapping <a class="header-anchor" href="#watch-a-mapping" aria-label="Permalink to “Watch a mapping”">​</a></h2><p>Create a <code>PortMapClient</code> with your plugin&#39;s message sender, then pass it to a <code>MappingWatcher</code> along with a request, a state-change callback, and a clock. The request needs a key that stays the same for this mapping, the local port, its protocol (<code>tcp</code> or <code>udp</code>), and a description for the router. Start the watcher after your plugin loads and call <code>tick()</code> from its task handler. The first request happens immediately; later checks keep the request alive and report state changes through the callback.</p><p>Use <code>openUrl(state)</code> when you need an HTTP base URL for the mapped port. It returns a URL only for an <code>open</code> state; while the mapping is pending, failed, unknown, or UPnPumpkin is unavailable, it returns <code>undefined</code>. An unavailable state can mean UPnPumpkin isn&#39;t installed, hasn&#39;t loaded yet, or couldn&#39;t answer. Handle it without preventing your own service from starting, and use the state callback to update the URL when the mapping opens.</p><p>Call <code>stop()</code> when your plugin unloads or the service no longer needs the port. By default, this releases the mapping immediately; pass <code>{ releasePort: false }</code> only when you want UPnPumpkin to keep it temporarily. If your plugin stops unexpectedly, UPnPumpkin removes requests after five minutes without a refresh. It also limits how many ports each plugin can request, as configured by <a href="/pumpkin-plugins/packages/upnpumpkin/README#configuration"><code>plugins.max_requests_per_plugin</code></a>.</p><p>UPnPumpkin only opens ports for plugins listed in <a href="/pumpkin-plugins/packages/upnpumpkin/README#configuration"><code>plugins.allowed</code></a>, which lists only BedrockAddonManager by default. Any other plugin gets a <code>failed</code> state whose reason names that setting, so tell server owners to add your plugin&#39;s name to the list.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};